INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0003-000000000001', 'b0000001-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 1, 'pasado-de-to-be-afirmativo', '{"es": "El Pasado de To Be: Was/Were (Afirmativo)", "en": "Past of To Be: Was/Were (Affirmative)"}'::jsonb, '{"es": "Aprende a usar was y were para hablar de identidad, ubicación, estados y el clima en el pasado.", "en": "Learn to use was and were to talk about identity, location, states, and weather in the past."}'::jsonb, 'grammar', 20, 12, '{"intro": "El verbo to be también tiene una forma en pasado: was y were. Se usan para hablar de identidad, ubicación, estados de ánimo o físicos, y el clima en el pasado. En esta lección aprenderás las formas afirmativas.", "sections": [{"type": "table", "title": "WAS O WERE", "headers": ["Sujeto", "Pasado de to be", "Ejemplo"], "rows": [["I", "was", "I was tired."], ["He / She / It", "was", "He was at home."], ["You", "were", "You were late."], ["We", "were", "We were at school."], ["They", "were", "They were happy."]]}, {"type": "explanation", "title": "USOS DE WAS/WERE", "text": "Was y were se usan para describir identidad (I was a student), ubicación (They were at the park), estados (She was hungry) y el clima (It was cold yesterday) en el pasado."}, {"type": "note", "variant": "tip", "text": "Was se usa con I, he, she, it (igual que el presente is). Were se usa con you, we, they (igual que el presente are). La relación con el presente te ayuda a recordar cuál usar."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0003-0001-000000000001', 'b0000002-0000-0000-0003-000000000001', 1, 'multiple_choice', '{"text": "Choose the correct form: I ___ at the park yesterday."}'::jsonb, '{"text": "was"}'::jsonb, '["were", "am", "is"]'::jsonb, '{"es": "Con I siempre se usa was en pasado."}'::jsonb, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0002-000000000001', 'b0000002-0000-0000-0003-000000000001', 2, 'fill_blank', '{"text": "She ___ very tired last night."}'::jsonb, '{"text": "was", "accepted": ["was"]}'::jsonb, NULL, '{"es": "She es tercera persona singular, por eso se usa was."}'::jsonb, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0003-000000000001', 'b0000002-0000-0000-0003-000000000001', 3, 'fill_blank', '{"text": "We ___ at the beach on Saturday."}'::jsonb, '{"text": "were", "accepted": ["were"]}'::jsonb, NULL, '{"es": "Con we siempre se usa were."}'::jsonb, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0004-000000000001', 'b0000002-0000-0000-0003-000000000001', 4, 'multiple_choice', '{"text": "Choose the correct form: They ___ happy with the results."}'::jsonb, '{"text": "were"}'::jsonb, '["was", "is", "are"]'::jsonb, '{"es": "They es plural, por eso se usa were, no was."}'::jsonb, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0005-000000000001', 'b0000002-0000-0000-0003-000000000001', 5, 'translation', '{"text": "Yo estaba en la escuela ayer."}'::jsonb, '{"text": "I was at school yesterday.", "accepted": ["I was at school yesterday."]}'::jsonb, NULL, NULL, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0006-000000000001', 'b0000002-0000-0000-0003-000000000001', 6, 'translation', '{"text": "Ellos estaban cansados anoche."}'::jsonb, '{"text": "They were tired last night.", "accepted": ["They were tired last night."]}'::jsonb, NULL, NULL, '{"grammar:past_to_be"}'),
('b0000003-0001-0003-0007-000000000001', 'b0000002-0000-0000-0003-000000000001', 7, 'multiple_choice', '{"text": "Choose the correct form: It ___ very cold yesterday morning."}'::jsonb, '{"text": "was"}'::jsonb, '["were", "is", "are"]'::jsonb, '{"es": "It es singular, por eso se usa was para hablar del clima en pasado."}'::jsonb, '{"grammar:past_to_be","vocab:weather"}'),
('b0000003-0001-0003-0008-000000000001', 'b0000002-0000-0000-0003-000000000001', 8, 'fill_blank', '{"text": "You ___ my best friend in school."}'::jsonb, '{"text": "were", "accepted": ["were"]}'::jsonb, NULL, '{"es": "Con you siempre se usa were, incluso en singular."}'::jsonb, '{"grammar:past_to_be"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0003-000000000002', 'b0000001-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 2, 'was-were-negativo-interrogativo', '{"es": "Was/Were: Negativo e Interrogativo", "en": "Was/Were: Negative and Interrogative"}'::jsonb, '{"es": "Aprende a formar oraciones negativas y preguntas con was y were, y a dar respuestas cortas.", "en": "Learn to form negative sentences and questions with was and were, and give short answers."}'::jsonb, 'grammar', 22, 13, '{"intro": "Ahora aprenderás a formar oraciones negativas (wasn''t/weren''t) y preguntas (Was/Were + sujeto...?) con el pasado de to be, además de respuestas cortas.", "sections": [{"type": "table", "title": "NEGATIVO E INTERROGATIVO", "headers": ["Sujeto", "Afirmativo", "Negativo", "Interrogativo"], "rows": [["I / He / She / It", "was", "wasn''t", "Was...?"], ["You / We / They", "were", "weren''t", "Were...?"]]}, {"type": "explanation", "title": "RESPUESTAS CORTAS", "text": "Para responder preguntas con was/were usamos respuestas cortas: ''Was she tired? Yes, she was. / No, she wasn''t.'' ''Were you at the party? Yes, I was. / No, I wasn''t.''"}, {"type": "note", "variant": "warning", "text": "Cuidado con la concordancia: no uses was con sujetos plurales. Incorrecto: ''They was tired.'' Correcto: ''They were tired.''"}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0003-0001-000000000001', 'b0000002-0000-0000-0003-000000000002', 1, 'multiple_choice', '{"text": "Choose the correct negative form: He ___ at school yesterday."}'::jsonb, '{"text": "wasn''t"}'::jsonb, '["weren''t", "isn''t", "don''t"]'::jsonb, '{"es": "He es singular, por eso la forma negativa correcta es wasn''t."}'::jsonb, '{"grammar:past_to_be_negative"}'),
('b0000003-0002-0003-0002-000000000001', 'b0000002-0000-0000-0003-000000000002', 2, 'fill_blank', '{"text": "They ___ at the party last night."}'::jsonb, '{"text": "weren''t", "accepted": ["weren''t", "were not"]}'::jsonb, NULL, '{"es": "They es plural, por eso se usa weren''t en la forma negativa."}'::jsonb, '{"grammar:past_to_be_negative"}'),
('b0000003-0002-0003-0003-000000000001', 'b0000002-0000-0000-0003-000000000002', 3, 'multiple_choice', '{"text": "Choose the correct question: ___ you tired after the trip?"}'::jsonb, '{"text": "Were"}'::jsonb, '["Was", "Are", "Do"]'::jsonb, '{"es": "Con you en preguntas de pasado se usa Were al inicio."}'::jsonb, '{"grammar:past_to_be_interrogative"}'),
('b0000003-0002-0003-0004-000000000001', 'b0000002-0000-0000-0003-000000000002', 4, 'fill_blank', '{"text": "___ she happy with her exam results?"}'::jsonb, '{"text": "Was", "accepted": ["Was"]}'::jsonb, NULL, '{"es": "She es singular, por eso la pregunta empieza con Was."}'::jsonb, '{"grammar:past_to_be_interrogative"}'),
('b0000003-0002-0003-0005-000000000001', 'b0000002-0000-0000-0003-000000000002', 5, 'translation', '{"text": "Ellos no estaban en casa."}'::jsonb, '{"text": "They weren''t at home.", "accepted": ["They weren''t at home.", "They were not at home."]}'::jsonb, NULL, NULL, '{"grammar:past_to_be_negative"}'),
('b0000003-0002-0003-0006-000000000001', 'b0000002-0000-0000-0003-000000000002', 6, 'translation', '{"text": "¿Estabas cansado ayer?"}'::jsonb, '{"text": "Were you tired yesterday?", "accepted": ["Were you tired yesterday?"]}'::jsonb, NULL, NULL, '{"grammar:past_to_be_interrogative"}'),
('b0000003-0002-0003-0007-000000000001', 'b0000002-0000-0000-0003-000000000002', 7, 'error_correction', '{"text": "They was hungry after school.", "error_word": "was"}'::jsonb, '{"text": "were"}'::jsonb, '["is", "are"]'::jsonb, '{"es": "They es plural, por eso el verbo correcto es were, no was."}'::jsonb, '{"grammar:past_to_be","grammar:subject_verb_agreement"}'),
('b0000003-0002-0003-0008-000000000001', 'b0000002-0000-0000-0003-000000000002', 8, 'error_correction', '{"text": "She were happy about the news.", "error_word": "were"}'::jsonb, '{"text": "was"}'::jsonb, '["is", "are"]'::jsonb, '{"es": "She es singular, por eso el verbo correcto es was, no were."}'::jsonb, '{"grammar:past_to_be","grammar:subject_verb_agreement"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0003-000000000003', 'b0000001-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 3, 'adjetivos-comparativos', '{"es": "Adjetivos Comparativos", "en": "Comparative Adjectives"}'::jsonb, '{"es": "Aprende a comparar personas, animales y cosas usando adjetivos comparativos: -er y more...than.", "en": "Learn to compare people, animals, and things using comparative adjectives: -er and more...than."}'::jsonb, 'grammar', 22, 14, '{"intro": "Los adjetivos comparativos sirven para comparar dos personas, animales o cosas, y en español equivalen a ''más...que''. La forma que se usa depende de la longitud del adjetivo.", "sections": [{"type": "table", "title": "REGLAS DE LOS COMPARATIVOS", "headers": ["Tipo de adjetivo", "Regla", "Ejemplo"], "rows": [["Cortos (1 sílaba)", "adjetivo + er + than", "tall -> taller than"], ["Cortos con consonante-vocal-consonante", "se dobla la última consonante + er + than", "big -> bigger than"], ["Cortos terminados en -y", "se cambia la y por i + er + than", "happy -> happier than"], ["Largos (2+ sílabas)", "more + adjetivo + than", "expensive -> more expensive than"], ["Irregulares", "forma especial, no sigue reglas", "good -> better than / bad -> worse than"]]}, {"type": "explanation", "title": "EJEMPLOS", "text": "My brother is taller than me. This car is bigger than that one. History is more interesting than math. Today the weather is better than yesterday."}, {"type": "note", "variant": "tip", "text": "Los irregulares good y bad no siguen ninguna regla: good -> better, bad -> worse. Debes memorizarlos."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0003-0001-000000000001', 'b0000002-0000-0000-0003-000000000003', 1, 'multiple_choice', '{"text": "Choose the correct comparative: A car is ___ than a bicycle."}'::jsonb, '{"text": "faster"}'::jsonb, '["fastest", "more fast", "fast"]'::jsonb, '{"es": "Fast es un adjetivo corto de una sílaba, por eso añade -er: faster."}'::jsonb, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0002-000000000001', 'b0000002-0000-0000-0003-000000000003', 2, 'fill_blank', '{"text": "This book is ___ (interesting) than that one."}'::jsonb, '{"text": "more interesting", "accepted": ["more interesting"]}'::jsonb, NULL, '{"es": "Interesting tiene más de dos sílabas, por eso se usa more interesting."}'::jsonb, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0003-000000000001', 'b0000002-0000-0000-0003-000000000003', 3, 'fill_blank', '{"text": "My brother is ___ (tall) than me."}'::jsonb, '{"text": "taller", "accepted": ["taller"]}'::jsonb, NULL, '{"es": "Tall es un adjetivo corto, por eso añade -er: taller."}'::jsonb, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0004-000000000001', 'b0000002-0000-0000-0003-000000000003', 4, 'multiple_choice', '{"text": "Choose the correct comparative: This exercise is ___ than the last one."}'::jsonb, '{"text": "more difficult"}'::jsonb, '["difficulter", "more difficulter", "difficultest"]'::jsonb, '{"es": "Difficult tiene tres sílabas, un adjetivo largo, por eso se usa more difficult."}'::jsonb, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0005-000000000001', 'b0000002-0000-0000-0003-000000000003', 5, 'translation', '{"text": "Este coche es más caro que ese."}'::jsonb, '{"text": "This car is more expensive than that one.", "accepted": ["This car is more expensive than that one."]}'::jsonb, NULL, NULL, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0006-000000000001', 'b0000002-0000-0000-0003-000000000003', 6, 'translation', '{"text": "Mi hermana es más alta que yo."}'::jsonb, '{"text": "My sister is taller than me.", "accepted": ["My sister is taller than me."]}'::jsonb, NULL, NULL, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0007-000000000001', 'b0000002-0000-0000-0003-000000000003', 7, 'reorder_words', '{"text": "Ordena la oración: bigger / house / is / than / your / My / house"}'::jsonb, '{"text": "My house is bigger than your house."}'::jsonb, NULL, '{"es": "El orden es: sujeto + is + adjetivo comparativo + than + el segundo elemento."}'::jsonb, '{"grammar:comparatives"}'),
('b0000003-0003-0003-0008-000000000001', 'b0000002-0000-0000-0003-000000000003', 8, 'fill_blank', '{"text": "The weather today is ___ (good) than yesterday."}'::jsonb, '{"text": "better", "accepted": ["better"]}'::jsonb, NULL, '{"es": "Good es irregular: su comparativo es better, no gooder."}'::jsonb, '{"grammar:comparatives"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0003-000000000004', 'b0000001-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 4, 'adjetivos-superlativos', '{"es": "Adjetivos Superlativos", "en": "Superlative Adjectives"}'::jsonb, '{"es": "Aprende a expresar el grado máximo de una cualidad usando adjetivos superlativos: the -est y the most.", "en": "Learn to express the highest degree of a quality using superlative adjectives: the -est and the most."}'::jsonb, 'grammar', 23, 14, '{"intro": "Los adjetivos superlativos sirven para comparar un elemento con todos los demás de un grupo, y en español equivalen a ''el/la más...''. Siempre se usan con the.", "sections": [{"type": "table", "title": "REGLAS DE LOS SUPERLATIVOS", "headers": ["Tipo de adjetivo", "Regla", "Ejemplo"], "rows": [["Cortos (1 sílaba)", "the + adjetivo + est", "tall -> the tallest"], ["Cortos con consonante-vocal-consonante", "se dobla la última consonante + the...est", "big -> the biggest"], ["Cortos terminados en -y", "se cambia la y por i + the...est", "happy -> the happiest"], ["Largos (2+ sílabas)", "the most + adjetivo", "expensive -> the most expensive"], ["Irregulares", "forma especial, no sigue reglas", "good -> the best / bad -> the worst"]]}, {"type": "explanation", "title": "EJEMPLOS", "text": "Everest is the highest mountain in the world. This is the most expensive restaurant in town. He is the best student in the class. That was the worst movie of the year."}, {"type": "note", "variant": "tip", "text": "El comparativo (lección anterior) compara solo dos elementos; el superlativo compara uno con todo un grupo. Recuerda usar siempre the antes del superlativo: the tallest, the most expensive, the best."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0004-0003-0001-000000000001', 'b0000002-0000-0000-0003-000000000004', 1, 'multiple_choice', '{"text": "Choose the correct superlative: This is ___ mountain in the world."}'::jsonb, '{"text": "the highest"}'::jsonb, '["higher", "the higher", "more high"]'::jsonb, '{"es": "High es un adjetivo corto, por eso el superlativo es the highest."}'::jsonb, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0002-000000000001', 'b0000002-0000-0000-0003-000000000004', 2, 'fill_blank', '{"text": "She is ___ (tall) student in the class."}'::jsonb, '{"text": "the tallest", "accepted": ["the tallest"]}'::jsonb, NULL, '{"es": "Tall es corto, por eso el superlativo es the tallest."}'::jsonb, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0003-000000000001', 'b0000002-0000-0000-0003-000000000004', 3, 'fill_blank', '{"text": "This is ___ (expensive) restaurant in the city."}'::jsonb, '{"text": "the most expensive", "accepted": ["the most expensive"]}'::jsonb, NULL, '{"es": "Expensive es un adjetivo largo, por eso el superlativo es the most expensive."}'::jsonb, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0004-000000000001', 'b0000002-0000-0000-0003-000000000004', 4, 'multiple_choice', '{"text": "Choose the correct superlative: He is ___ student in our school."}'::jsonb, '{"text": "the best"}'::jsonb, '["the goodest", "the better", "the most good"]'::jsonb, '{"es": "Good es irregular: su superlativo es the best, no the goodest."}'::jsonb, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0005-000000000001', 'b0000002-0000-0000-0003-000000000004', 5, 'translation', '{"text": "Este es el hotel más barato de la ciudad."}'::jsonb, '{"text": "This is the cheapest hotel in the city.", "accepted": ["This is the cheapest hotel in the city."]}'::jsonb, NULL, NULL, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0006-000000000001', 'b0000002-0000-0000-0003-000000000004', 6, 'translation', '{"text": "Ella es la peor estudiante de la clase."}'::jsonb, '{"text": "She is the worst student in the class.", "accepted": ["She is the worst student in the class."]}'::jsonb, NULL, NULL, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0007-000000000001', 'b0000002-0000-0000-0003-000000000004', 7, 'reorder_words', '{"text": "Ordena la oración: is / biggest / animal / The / elephant / the / in / the / world"}'::jsonb, '{"text": "The elephant is the biggest animal in the world."}'::jsonb, NULL, '{"es": "El orden es: sujeto + is + the + adjetivo superlativo + sustantivo + in the world."}'::jsonb, '{"grammar:superlatives"}'),
('b0000003-0004-0003-0008-000000000001', 'b0000002-0000-0000-0003-000000000004', 8, 'fill_blank', '{"text": "Today is ___ (hot) day of the year."}'::jsonb, '{"text": "the hottest", "accepted": ["the hottest"]}'::jsonb, NULL, '{"es": "Hot es un adjetivo corto con patrón consonante-vocal-consonante, por eso se dobla la t: the hottest."}'::jsonb, '{"grammar:superlatives"}');
